package com.fintrack.khmtomnenh.order.controller; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.order.dto.OrderDto; import com.fintrack.khmtomnenh.order.entity.Order; import com.fintrack.khmtomnenh.order.service.OrderService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/orders") @RequiredArgsConstructor public class OrderController {private final OrderService s;@PostMapping("/accept/{quotationId}") public ResponseEntity<Order> accept(@PathVariable Long quotationId,@AuthenticationPrincipal Auth a){return ResponseEntity.status(HttpStatus.CREATED).body(s.accept(quotationId,a));}@GetMapping public List<Order> mine(@AuthenticationPrincipal Auth a){return s.mine(a);}@GetMapping("/{id}") public Order get(@PathVariable Long id){return s.get(id);}@PatchMapping("/{id}/status") public Order status(@PathVariable Long id,@Valid @RequestBody OrderDto d,@AuthenticationPrincipal Auth a){return s.updateStatus(id,d,a);}}
